def frog_jump(a: int, b: int, k: int) -> int:
    full_cycles = k // 4
    remaining_jumps = k % 4

    position = full_cycles * (a - b)

    if remaining_jumps == 1:
        position += a
    elif remaining_jumps == 2:
        position += a - b
    elif remaining_jumps == 3:
        position -= b

    return position

